from pathlib import Path

path = Path('lib/main.dart')
src = path.read_text(encoding='utf-8')

old_dashboard = '''                GridView.count(\n                  crossAxisCount: 2,\n                  crossAxisSpacing: 13,\n                  mainAxisSpacing: 13,\n                  shrinkWrap: true,\n                  physics: const NeverScrollableScrollPhysics(),\n                  childAspectRatio: 1.0,\n                  children: <Widget>[\n                    _MetricCard(\n                      icon: Icons.volunteer_activism_rounded,\n                      label: 'To Receive (+)',\n                      value: _money(totals.toReceive),\n                      color: appleGreen,\n                    ),\n                    _MetricCard(\n                      icon: Icons.request_quote_rounded,\n                      label: 'To Pay (-)',\n                      value: _money(totals.toPay),\n                      color: appleRed,\n                    ),\n                    _MetricCard(\n                      icon: Icons.receipt_long_rounded,\n                      label: 'Month Expense',\n                      value: _money(totals.monthExpense),\n                      color: diaryOrange,\n                    ),\n                    _MetricCard(\n                      icon: Icons.trending_up_rounded,\n                      label: 'Month Profit',\n                      value: _signedMoney(totals.monthProfit),\n                      color: appleBlue,\n                    ),\n                  ],\n                ),'''

new_dashboard = '''                LayoutBuilder(\n                  builder: (BuildContext context, BoxConstraints constraints) {\n                    const double gap = 13;\n                    const double minimumCardHeight = 156;\n                    final double cardWidth = (constraints.maxWidth - gap) / 2;\n                    final double ratio =\n                        math.min(1.0, cardWidth / minimumCardHeight);\n                    return GridView.count(\n                      crossAxisCount: 2,\n                      crossAxisSpacing: gap,\n                      mainAxisSpacing: gap,\n                      shrinkWrap: true,\n                      physics: const NeverScrollableScrollPhysics(),\n                      childAspectRatio: ratio,\n                      children: <Widget>[\n                        _MetricCard(\n                          icon: Icons.volunteer_activism_rounded,\n                          label: 'To Receive (+)',\n                          value: _money(totals.toReceive),\n                          color: appleGreen,\n                        ),\n                        _MetricCard(\n                          icon: Icons.request_quote_rounded,\n                          label: 'To Pay (-)',\n                          value: _money(totals.toPay),\n                          color: appleRed,\n                        ),\n                        _MetricCard(\n                          icon: Icons.receipt_long_rounded,\n                          label: 'Month Expense',\n                          value: _money(totals.monthExpense),\n                          color: diaryOrange,\n                        ),\n                        _MetricCard(\n                          icon: Icons.trending_up_rounded,\n                          label: 'Month Profit',\n                          value: _signedMoney(totals.monthProfit),\n                          color: appleBlue,\n                        ),\n                      ],\n                    );\n                  },\n                ),'''

if src.count(old_dashboard) != 1:
    raise SystemExit(f'Dashboard grid block count={src.count(old_dashboard)}')
src = src.replace(old_dashboard, new_dashboard, 1)

old_business = '''                      GridView.count(\n                        crossAxisCount: 2,\n                        crossAxisSpacing: 11,\n                        mainAxisSpacing: 11,\n                        shrinkWrap: true,\n                        physics: const NeverScrollableScrollPhysics(),\n                        childAspectRatio: 1.55,\n                        children:\n                            totals.entries.map((MapEntry<String, double> item) {\n                          final _BusinessTone tone = _businessTones[item.key]!;\n                          return _GlassCard(\n                            padding: const EdgeInsets.all(13),\n                            borderRadius: 19,\n                            borderColor: tone.color.withAlpha(60),\n                            shadowColor: tone.color.withAlpha(20),\n                            child: Column(\n                              mainAxisAlignment: MainAxisAlignment.center,\n                              crossAxisAlignment: CrossAxisAlignment.start,\n                              children: <Widget>[\n                                Text(\n                                  tone.label,\n                                  maxLines: 1,\n                                  overflow: TextOverflow.ellipsis,\n                                  style: TextStyle(\n                                    color: tone.color,\n                                    fontSize: 9,\n                                    fontWeight: FontWeight.w900,\n                                  ),\n                                ),\n                                const SizedBox(height: 5),\n                                Text(\n                                  _money(item.value),\n                                  style: TextStyle(\n                                    color: tone.color,\n                                    fontSize: 19,\n                                    fontWeight: FontWeight.w900,\n                                    fontFeatures: AppStyles.tabularFigures,\n                                  ),\n                                ),\n                              ],\n                            ),\n                          );\n                        }).toList(),\n                      ),'''

new_business = '''                      LayoutBuilder(\n                        builder:\n                            (BuildContext context, BoxConstraints constraints) {\n                          const double gap = 11;\n                          const double preferredRatio = 1.55;\n                          const double minimumCardHeight = 86;\n                          final double cardWidth =\n                              (constraints.maxWidth - gap) / 2;\n                          final double ratio = math.min(\n                            preferredRatio,\n                            cardWidth / minimumCardHeight,\n                          );\n                          return GridView.count(\n                            crossAxisCount: 2,\n                            crossAxisSpacing: gap,\n                            mainAxisSpacing: gap,\n                            shrinkWrap: true,\n                            physics: const NeverScrollableScrollPhysics(),\n                            childAspectRatio: ratio,\n                            children: totals.entries\n                                .map((MapEntry<String, double> item) {\n                              final _BusinessTone tone =\n                                  _businessTones[item.key]!;\n                              return _GlassCard(\n                                padding: const EdgeInsets.all(13),\n                                borderRadius: 19,\n                                borderColor: tone.color.withAlpha(60),\n                                shadowColor: tone.color.withAlpha(20),\n                                child: Column(\n                                  mainAxisAlignment: MainAxisAlignment.center,\n                                  crossAxisAlignment: CrossAxisAlignment.start,\n                                  children: <Widget>[\n                                    Text(\n                                      tone.label,\n                                      maxLines: 1,\n                                      overflow: TextOverflow.ellipsis,\n                                      style: TextStyle(\n                                        color: tone.color,\n                                        fontSize: 9,\n                                        fontWeight: FontWeight.w900,\n                                      ),\n                                    ),\n                                    const SizedBox(height: 5),\n                                    Text(\n                                      _money(item.value),\n                                      style: TextStyle(\n                                        color: tone.color,\n                                        fontSize: 19,\n                                        fontWeight: FontWeight.w900,\n                                        fontFeatures: AppStyles.tabularFigures,\n                                      ),\n                                    ),\n                                  ],\n                                ),\n                              );\n                            }).toList(),\n                          );\n                        },\n                      ),'''

if src.count(old_business) != 1:
    raise SystemExit(f'Business grid block count={src.count(old_business)}')
src = src.replace(old_business, new_business, 1)

path.write_text(src, encoding='utf-8')
print('PATCH_OK adaptive dashboard/business grid geometry installed')
